const EMAIL_RE = /^[^\s@]+@[^\s@]+$/;

export function dedupeEmails(list) {
  if (!Array.isArray(list)) {
    throw new TypeError('dedupeEmails expects an array of email address strings');
  }
  const seen = new Set();
  const result = [];
  for (const entry of list) {
    if (typeof entry !== 'string') {
      throw new TypeError(`dedupeEmails expects only strings, got ${typeof entry}`);
    }
    const email = entry.trim();
    if (email === '' || !EMAIL_RE.test(email)) {
      throw new TypeError(`invalid email address: ${JSON.stringify(entry)}`);
    }
    const key = email.toLowerCase();
    if (!seen.has(key)) {
      seen.add(key);
      result.push(email.toLowerCase());
    }
  }
  return result;
}

