const UNIT_SECONDS = Object.freeze({ h: 3600, m: 60, s: 1 });

/**
 * Parse a compact duration string like "1h30m" into a total number of seconds.
 *
 * Units: h (hours), m (minutes), s (seconds). Each unit may appear at most
 * once, in any order. Numbers must be non-negative integers.
 *
 * @param {string} s the duration string to parse
 * @returns {number} total seconds
 * @throws {TypeError}  when the input is not a string
 * @throws {SyntaxError} when the input is empty or contains characters that
 *   are not a sequence of `<digits><unit>` tokens
 * @throws {RangeError} when a component or the total exceeds the safe integer
 *   range
 */
export function parseDuration(s) {
  if (typeof s !== 'string') {
    throw new TypeError('parseDuration: expected a string');
  }

  const tokenPattern = /(\d+)([hms])/g;
  const tokens = s.match(tokenPattern);

  // Every character must be consumed by tokens, so the concatenated tokens
  // must equal the input exactly. This rejects empty input, stray characters,
  // whitespace, signs, decimals, and unknown units.
  if (!tokens || tokens.join('') !== s) {
    throw new SyntaxError(`parseDuration: invalid duration string ${JSON.stringify(s)}`);
  }

  const seen = new Set();
  let total = 0;

  for (const token of tokens) {
    const match = /^(\d+)([hms])$/.exec(token);
    const value = Number(match[1]);
    const unit = match[2];

    if (seen.has(unit)) {
      throw new SyntaxError(`parseDuration: repeated unit "${unit}" in ${JSON.stringify(s)}`);
    }
    seen.add(unit);

    if (!Number.isSafeInteger(value)) {
      throw new RangeError(`parseDuration: component out of range in ${JSON.stringify(s)}`);
    }

    total += value * UNIT_SECONDS[unit];

    if (!Number.isSafeInteger(total)) {
      throw new RangeError(`parseDuration: total out of range in ${JSON.stringify(s)}`);
    }
  }

  return total;
}

