  if (typeof s !== 'string') {
    throw new TypeError(`parseDuration: expected a string, got ${typeof s}`);
  }
  if (s.length === 0) {
    throw new Error('parseDuration: duration string must not be empty');
  }

  const tokenPattern = /(\d+)([hms])/g;
  let total = 0;
  let consumed = 0;
  let match;

  while ((match = tokenPattern.exec(s)) !== null) {
    total += Number(match[1]) * UNIT_SECONDS[match[2]];
    consumed += match[0].length;
  }

  if (consumed !== s.length) {
    throw new Error(`parseDuration: invalid duration string ${JSON.stringify(s)}`);
  }
  if (!Number.isSafeInteger(total)) {
    throw new RangeError(`parseDuration: total exceeds Number.MAX_SAFE_INTEGER for ${JSON.stringify(s)}`);
  }

  return total;
}

