    throw new Error('parseRange: input must be a non-empty string');
  }

  const tokens = s.split(',');
  const seen = new Set();

  for (const rawToken of tokens) {
    const token = rawToken.trim();
    if (token === '') {
      throw new Error(`parseRange: empty token`);
    }

    const parts = token.split('-');
    if (parts.length > 2) {
      throw new Error(`parseRange: malformed token "${token}"`);
    }

    if (parts.length === 1) {
      seen.add(parseNum(parts[0], token));
    } else {
      const a = parseNum(parts[0], token);
      const b = parseNum(parts[1], token);
      if (a > b) {
        throw new Error(`parseRange: reversed range "${token}"`);
      }
      for (let i = a; i <= b; i++) {
        seen.add(i);
      }
    }
  }

  return [...seen].sort((x, y) => x - y);
}

